function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 80000) return 'nums needs 1 to 80000 values.';
  if (k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  if (nums.some(v => v < -1000000 || v > 1000000)) return 'Each value is between -10^6 and 10^6.';
  return null;
}

