function minMaxSubarraySum(nums, k) {
  const n = nums.length;
  const pairs = x => (x > 0 ? (x * (x + 1)) / 2 : 0);
  const count = (left, right) => pairs(k) - pairs(k - left) - pairs(k - right) + pairs(k - left - right);

  const extremeSum = beats => {
    const prev = new Array(n).fill(-1);
    const next = new Array(n).fill(n);
    const stack = [];
    for (let i = 0; i < n; i++) {
      while (stack.length > 0 && beats(nums[i], nums[stack[stack.length - 1]])) {
        next[stack.pop()] = i;
      }
      if (stack.length > 0) {
        prev[i] = stack[stack.length - 1];
      }
      stack.push(i);
    }
    let sum = 0;
    for (let i = 0; i < n; i++) {
      sum += nums[i] * count(i - prev[i], next[i] - i);
    }
    return sum;
  };

  return extremeSum((a, b) => a > b) + extremeSum((a, b) => a < b);
}

