function minMaxSubarraySum(nums, k) {
  // Grow every subarray from each start, up to k elements, tracking its smallest and largest value.
  let total = 0;
  for (let start = 0; start < nums.length; start++) {
    let low = Infinity, high = -Infinity;
    for (let end = start; end < nums.length && end - start < k; end++) {
      low = Math.min(low, nums[end]);
      high = Math.max(high, nums[end]);
      total += low + high;
    }
  }
  return total;
}

