function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 2000 : 1 + pick(10);
  // k is 1, the whole length, or anything between.
  const choice = pick(4);
  const k = choice === 0 ? 1 : choice === 1 ? n : 1 + pick(n);
  // Values span the full range or only a few, so ties are common; some arrays are sorted up or down.
  const span = large ? [1000000, 3, 1000][pick(3)] : [5, 1, 1000000][pick(3)];
  const nums = Array.from({ length: n }, () => pick(2 * span + 1) - span);
  const order = pick(4);
  if (order === 1) nums.sort((a, b) => a - b);
  if (order === 2) nums.sort((a, b) => b - a);
  return [nums, k];
}
